import{_ as l,o as e,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"New workload balancer in Ceph","description":"","frontmatter":{"title":"New workload balancer in Ceph","date":"2022-11-15T00:00:00.000Z","updated":"2022-11-16T00:00:00.000Z","tags":["Ceph","Distributed Storage","CRUSH Algorithm","Workload Balancer","Performance Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/New_workload_balancer_in_Ceph.md","filePath":"posts/2022/New_workload_balancer_in_Ceph.md","lastUpdated":1780459816000}'),o={name:"posts/2022/New_workload_balancer_in_Ceph.md"};function t(n,a,d,s,h,c){return e(),i("div",null,[...a[0]||(a[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议参与者" tabindex="-1">会议参与者 <a class="header-anchor" href="#会议参与者" aria-label="Permalink to &quot;会议参与者&quot;">​</a></h4><ul><li>Joe Solomon：前架构师，现为Red Hat的CTO办公室新兴技术团队成员。</li><li>Laura Flores：Red Hat的RADOS核心团队成员，专注于上游测试。</li></ul><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><ul><li>介绍Reef版本中即将引入的新工作负载平衡器。</li></ul><h4 id="讨论内容" tabindex="-1">讨论内容 <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容&quot;">​</a></h4><ol><li><p><strong>动机与背景</strong></p><ul><li>当前Ceph在高负载下性能受限于最弱环节。</li><li>现有容量平衡器保证OSD间容量均匀分布，但未解决读取平衡问题。</li><li>CRUSH算法在大型集群中平衡读取，但在小型集群中表现不佳。</li></ul></li><li><p><strong>现有问题与改进</strong></p><ul><li>对多种系统OSD Mark文件进行测试。</li><li>重构现有平衡器代码，提高可读性和可修改性。</li><li>创建新的工作负载平衡器，考虑读取操作。</li></ul></li><li><p><strong>新rebalancer设计</strong></p><ul><li>新rebalancer主要针对小型集群，设计基于池的读取平衡。</li><li>考虑读写工作负载差异，未来版本将考虑设备大小和性能波动。</li></ul></li><li><p><strong>功能与实现</strong></p><ul><li>引入新命令改变PG的主OSD，不涉及数据移动。</li><li>实现两个主要函数：<code>calc desired primary distribution</code>和<code>balanced primaries</code>。</li></ul></li><li><p><strong>演示与测试</strong></p><ul><li>展示了新rebalancer在不同场景下改善读取平衡。</li><li>强调未来将进行更多上游测试和性能测试。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>新rebalancer将在Reef版本中作为离线工具提供，未来计划集成到自动平衡模块中。</li><li>未来版本将考虑设备大小和动态性能调整。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续进行上游测试和性能测试。</li><li>考虑将新rebalancer集成到自动平衡模块中。</li><li>探索更复杂的平衡策略，如基于设备大小和动态性能调整。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h4><ul><li>讨论了primary affinity的潜在改进和客户端读取策略的复杂性。</li><li>强调了未来版本中可能考虑的更高级平衡策略。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>感谢所有参与者的提问和讨论。</li><li>分享了相关GitHub仓库链接，以便进一步交流和反馈。</li></ul><p>本次会议纪要准确反映了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划，并保留了Ceph相关领域的英文原文关键词。</p>',16)])])}const _=l(o,[["render",t]]);export{p as __pageData,_ as default};
